<script lang="ts">import type { Snippet } from 'svelte'; import type { HTMLAttributes } from 'svelte/elements'; import { getMenuCheckboxContext } from './menu-context.svelte.js'; export interface Props extends Omit<HTMLAttributes<HTMLSpanElement>, 'children'> { children?: Snippet; keepMounted?: boolean; ref?: HTMLSpanElement | null; } let { children, keepMounted = false, ref = $bindable(null), ...rest }: Props = $props(); const checkbox = getMenuCheckboxContext();</script>
{#if keepMounted || checkbox.checked}<span bind:this={ref} {...rest} hidden={!checkbox.checked} aria-hidden="true" data-checked={checkbox.checked ? '' : undefined}>{@render children?.()}</span>{/if}
